def transform(grid):
 h,w=len(grid),len(grid[0])
 def comps(color):
  remaining={(r,c) for r in range(h) for c in range(w) if grid[r][c]==color}; out=[]
  while remaining:
   p=remaining.pop(); s={p}; stack=[p]
   while stack:
    r,c=stack.pop()
    for dr in (-1,0,1):
     for dc in (-1,0,1):
      q=(r+dr,c+dc)
      if q in remaining: remaining.remove(q);s.add(q);stack.append(q)
   out.append(s)
  return out
 pieces=comps(2)
 pieces.sort(key=len,reverse=True)
 def fit(target):
  if len(target)!=sum(map(len,pieces)): return False
  def rec(i,left):
   if i==len(pieces): return not left
   piece=pieces[i]; a,b=next(iter(piece))
   for x,y in left:
    moved={(r+x-a,c+y-b) for r,c in piece}
    if moved<=left and rec(i+1,left-moved):return True
   return False
  return rec(0,target)
 out=[[0 if v==2 else v for v in row] for row in grid]
 for obj in comps(5):
  if fit(obj):
   for r,c in obj:out[r][c]=2
 return out

